const lessons=[{"date": "24.11", "title": "Фундамент ИБ", "tag": "Основы", "blocks": [["CIA и бизнес", "Конфиденциальность — доступ только уполномоченным; целостность — защита от неправомерного изменения; доступность — возможность использовать ресурс вовремя. Утечка зарплат нарушает C; подмена реквизитов — I; остановка портала — A."], ["Актив, угроза, уязвимость, риск", "Актив имеет ценность. Угроза — потенциальная причина ущерба, уязвимость — слабость, риск — вероятность и последствия сценария. Пример: клиентская БД → несанкционированный доступ через слабый пароль → возможная утечка."], ["Управление риском", "Исходный риск оценивают без мер, остаточный — после них. Обработка: снижение (MFA), избегание (отказ от сервиса), передача части последствий (страхование), принятие уполномоченным владельцем. Балльная модель P × I — условная, не универсальная."], ["Меры защиты", "Организационные, технические и физические. По функциям: предупреждение, обнаружение, коррекция, восстановление. SIEM преимущественно обнаруживает; NGFW контролирует сеть, EDR обнаруживает и реагирует на хосте. Defense in Depth — взаимодополняющие меры."], ["Роль РП", "Сначала активы, риски и обязательные требования, затем меры, технические требования, архитектура, бюджет, внедрение и критерии приёмки. Не покупаем продукт без цели."]], "case": ["Риск компрометации", "У компании внешняя почта, нет MFA, пароль администратора слабый. Бизнес опасается утечки переписки. Какие действия непосредственно уменьшают вероятность использования украденного пароля?", ["Настроить MFA и усилить пароль", "Увеличить срок хранения журналов", "Купить резервный диск", "Принять риск без оценки"], [0], "MFA и сильный пароль воздействуют на сценарий входа. Журналы помогают обнаружить инцидент, а копии — восстановиться."], "questions": [{"q": "Пользователь изменил реквизиты платежа без разрешения, сервис продолжает работать. Что нарушено непосредственно?", "o": ["Доступность", "Целостность", "Конфиденциальность", "Неотказуемость"], "a": [1], "e": "Подмена значения нарушает целостность."}, {"q": "Сервис доступен, но стороннему лицу стали видны зарплаты. Какое свойство нарушено?", "o": ["Целостность", "Доступность", "Конфиденциальность", "Отказоустойчивость"], "a": [2], "e": "Несанкционированное раскрытие — конфиденциальность."}, {"q": "Внешний портал использует неисправленное ПО. Что из перечисленного является уязвимостью?", "o": ["Вероятность утечки", "Несанкционированный доступ", "Устаревшая версия с известным дефектом", "Потери выручки"], "a": [2], "e": "Уязвимость — слабость, а не событие или ущерб."}, {"q": "Риск простоя оценён 4×5. После резервирования последствия оценены на 2, вероятность не изменилась. Новый балл?", "o": ["10", "8", "20", "6"], "a": [1], "e": "4 × 2 = 8; оценка условна."}, {"q": "Организация закрыла сервис и прекратила создававшую риск деятельность. Это…", "o": ["Снижение", "Принятие", "Избегание", "Передача"], "a": [2], "e": "Отказ от деятельности — избегание."}, {"q": "Страховка покрывает часть финансовых потерь от атаки. Какой способ применён?", "o": ["Передача", "Снижение вероятности атаки", "Избегание", "Устранение угрозы"], "a": [0], "e": "Часть последствий передаётся страховщику."}, {"q": "Какие утверждения об остаточном риске верны?", "o": ["Он остаётся после мер защиты", "Он всегда равен нулю после приёмки", "Его оценивают с учётом эффективности мер", "Инженер автоматически вправе принять любой риск"], "a": [0, 2], "e": "Эффективность мер влияет на остаточный риск; принятие требует полномочий."}, {"q": "Какое средство прежде всего обнаруживает взаимосвязанные события из разных систем?", "o": ["PAM", "SIEM", "Backup", "VLAN"], "a": [1], "e": "SIEM централизованно анализирует события."}, {"q": "Что лучше всего описывает Defense in Depth?", "o": ["Дублирование одной лицензии", "Единая точка защиты всех активов", "Независимые взаимодополняющие меры", "Обязательное шифрование всех журналов"], "a": [2], "e": "Несколько уровней снижают зависимость от одного механизма."}, {"q": "Заказчик хочет приобрести SIEM. Какой результат нужен первым для обоснования выбора?", "o": ["Перечень целей, активов, угроз и требований", "Готовые правила корреляции любого вендора", "Акт приёмки", "Максимальная конфигурация сервера"], "a": [0], "e": "Требования определяют нужный функционал и объём работ."}]}, {"date": "30.11", "title": "ИТ-инфраструктура предприятия", "tag": "Архитектура", "blocks": [["Клиент и сервер", "Клиент запрашивает услугу, сервер её предоставляет. Приложение, СУБД, файловое хранилище и службы идентификации могут находиться на разных узлах. ЦОД — площадка размещения вычислительной и сетевой инфраструктуры."], ["CPU, RAM, SSD, виртуализация", "CPU выполняет вычисления, RAM хранит рабочие данные временно, SSD/HDD сохраняют данные долговременно. Гипервизор распределяет ресурсы физического хоста между виртуальными машинами; отказ хоста затрагивает его ВМ без HA. Контейнеры обычно используют ядро хоста."], ["AD и СУБД", "AD DS централизует доменные учётные записи, компьютеры и группы. Контроллеры домена обслуживают каталог и аутентификацию. Kerberos — протокол аутентификации; LDAP — доступ к каталогу; GPO — групповые политики. СУБД управляет структурированными данными, запросами и транзакциями."], ["Зоны и зависимости", "Публичные сервисы могут находиться в DMZ, внутренние БД — в отдельной зоне. Между ними разрешают только необходимые соединения. Схема: пользователь → веб-сервис → приложение → СУБД; AD, DNS, NTP и backup — обеспечивающие сервисы."], ["РП и обследование", "Собираем реестр активов, владельцев, ОС, версии, сетевые зоны, зависимости, критичность и окна работ. Оцениваем ресурсы, доступы, отказоустойчивость и ограничения."]], "case": ["Архитектор на обследовании", "Публичный портал использует БД и AD. Что лучше согласовать до развертывания нового СЗИ?", ["Матрицу сетевых потоков, владельцев и зависимости", "Только имя виртуальной машины", "Только адрес публичного сайта", "Цвет интерфейса SIEM"], [0], "Зависимости и потоки помогают избежать нарушения рабочих сервисов."], "questions": [{"q": "Гипервизор отказал, HA нет. Какие объекты наиболее непосредственно затронуты?", "o": ["Все компьютеры предприятия", "ВМ на отказавшем хосте", "Все реплики БД независимо от размещения", "Только DNS-кэш"], "a": [1], "e": "ВМ зависят от физического хоста без механизма переключения."}, {"q": "Какой ресурс отвечает за временные рабочие данные коррелятора?", "o": ["SSD", "CPU", "RAM", "DNS"], "a": [2], "e": "RAM — оперативная память."}, {"q": "Сотрудника добавили в доменную группу. Что это обеспечивает?", "o": ["Возможность назначать доступ через членство в группе", "Гарантированную доступность всех серверов", "Создание резервной копии", "Автоматическую сетевую изоляцию"], "a": [0], "e": "Группы используются в механизмах авторизации."}, {"q": "Какой протокол применяется для доступа к объектам каталога?", "o": ["NTP", "SMTP", "LDAP", "Syslog"], "a": [2], "e": "LDAP — протокол доступа к каталогу."}, {"q": "Что является функцией GPO?", "o": ["Хранение транзакций", "Централизованное применение политик домена", "Шифрование любых сетевых пакетов", "Резервирование питания"], "a": [1], "e": "Group Policy управляет настройками пользователей и компьютеров."}, {"q": "Где логичнее разместить публичный веб-сервис при классической зональной архитектуре?", "o": ["В сети резервного копирования", "В административной сети", "В домене без фильтрации", "В DMZ с ограниченными связями"], "a": [3], "e": "DMZ отделяет публичный сервис от внутренних ресурсов."}, {"q": "Какие зависимости стоит проверить для нового сервера SIEM?", "o": ["DNS и NTP", "Сетевые потоки и порты", "Цвет корпуса", "Хранилище и вычислительные ресурсы"], "a": [0, 1, 3], "e": "Эти компоненты влияют на функционирование."}, {"q": "Сервер приложения исправен, но его БД недоступна. Что важнее всего учитывать?", "o": ["Наличие браузера", "Зависимость бизнес-сервиса от БД", "Марку монитора", "Количество пользователей AD само по себе"], "a": [1], "e": "Исправность отдельных узлов не равна доступности сервиса."}, {"q": "Что отличает СУБД от файловой системы?", "o": ["Она всегда работает без диска", "Она заменяет AD", "Она управляет запросами, структурой и транзакциями данных", "Она всегда является гипервизором"], "a": [2], "e": "Это базовые функции СУБД."}, {"q": "Что должно выйти из обследования перед проектированием?", "o": ["Только список IP", "Только акт поставки", "Только счёт на лицензии", "Инвентаризация, зависимости, критичность и ограничения"], "a": [3], "e": "Эти сведения формируют требования к архитектуре."}]}, {"date": "01.12", "title": "Компьютерные сети", "tag": "Сети", "blocks": [["OSI и TCP/IP", "OSI: физический, канальный, сетевой, транспортный, сеансовый, представления, прикладной. Ethernet/MAC — L2, IP/маршрутизация — L3, TCP/UDP/порты — L4, HTTP/DNS — прикладные протоколы. Реальные стеки не всегда точно соответствуют семи уровням."], ["TCP и UDP", "TCP устанавливает соединение (SYN, SYN-ACK, ACK), обеспечивает упорядоченный поток и повторную передачу. UDP — датаграммы без встроенных гарантий доставки или порядка. Успешное TCP-соединение не доказывает обработку приложением."], ["Адреса и порты", "IP идентифицирует сетевой интерфейс, порт — конечную точку транспорта приложения. /24 означает 24 бита сетевой части IPv4. TCP 443 обычно HTTPS, TCP 22 SSH, UDP/TCP 53 DNS; реальные порты настраиваются."], ["Диагностика", "ping — ICMP, traceroute — путь, nc -zv HOST PORT — TCP-порт, ss -tulnp — слушающие сокеты Linux, tcpdump — пакеты. Проверяем источник, маршрут, фильтрацию, порт и приложение. UDP проверяем по фактическим датаграммам и журналам."]], "case": ["Пропали события", "Источник отвечает на ping, но TCP 514 не соединяется. Что проверить следующим?", ["Сразу менять парсер", "Маршрут, ACL, МЭ и наличие слушающего TCP-порта", "Сменить логин аналитика", "Очистить хранилище"], [1], "ICMP не подтверждает доступность TCP; проверяем транспорт и слушающий сервис."], "questions": [{"q": "Какая пара соответствует уровням?", "o": ["IP — L3, TCP — L4", "IP — L4, TCP — L2", "Ethernet — L7, DNS — L2", "UDP — L3, HTTP — L1"], "a": [0], "e": "IP маршрутизируется на L3, TCP работает на L4."}, {"q": "Syslog использует UDP. Что может произойти при потере датаграммы?", "o": ["UDP автоматически восстанавливает событие", "UDP не гарантирует повторную передачу", "Событие всегда дублируется", "SIEM гарантированно получит событие"], "a": [1], "e": "UDP не обеспечивает надёжную доставку."}, {"q": "Как выглядит стандартное установление TCP-соединения?", "o": ["ACK → SYN → FIN", "SYN → ACK → RST", "SYN → SYN-ACK → ACK", "FIN → SYN → ACK"], "a": [2], "e": "Трёхстороннее рукопожатие TCP."}, {"q": "Какая команда показывает слушающие сокеты на Linux?", "o": ["df -h", "journalctl -n 10", "ping", "ss -tulnp"], "a": [3], "e": "ss показывает сокеты и порты."}, {"q": "TCP-соединение устанавливается, но приложение возвращает ошибку. Какой вывод корректен?", "o": ["Транспорт доступен, надо проверить прикладной уровень", "Сеть гарантированно без проблем", "Данные точно сохранены", "Нужно отключить все ACL"], "a": [0], "e": "TCP не подтверждает корректность работы приложения."}, {"q": "Какие средства полезны для проверки доставки UDP-событий?", "o": ["tcpdump на приёмнике", "Журнал принимающего приложения", "Только ping", "Только свободная RAM"], "a": [0, 1], "e": "Проверяем фактические датаграммы и обработку."}, {"q": "Что означает /24 для IPv4?", "o": ["24 открытых порта", "24 бита сетевого префикса", "24 хоста", "24 маршрута"], "a": [1], "e": "CIDR задаёт длину префикса."}, {"q": "Два сервиса на одном IP используют TCP 22 и TCP 443. Что разделяет соединения?", "o": ["Только MAC", "Только имя пользователя", "Транспортные порты", "Объём диска"], "a": [2], "e": "Порты различают транспортные конечные точки."}, {"q": "На каком уровне обычно работает маршрутизация IP?", "o": ["L2", "L4", "L7", "L3"], "a": [3], "e": "IP — сетевой уровень."}, {"q": "Пакеты видны на источнике, но отсутствуют на интерфейсе приёмника. Что первично исследовать?", "o": ["Парсер SIEM", "Сетевой путь и фильтрацию между узлами", "Правило корреляции", "Роль аналитика"], "a": [1], "e": "Проблема локализована до приёмника."}]}, {"date": "02.12", "title": "Сетевые технологии и диагностика", "tag": "Сети", "blocks": [["DNS и DHCP", "DNS сопоставляет имена с записями (A/AAAA, CNAME, MX и др.). DHCP выдаёт параметры сети: IP, маску, шлюз, DNS. DNS не гарантирует доступность сервиса."], ["NAT и прокси", "SNAT меняет адрес источника, DNAT — назначения. NAT не заменяет фильтрацию. Forward proxy обслуживает клиентов, reverse proxy принимает запросы к внутренним сервисам."], ["VLAN, DMZ, ACL", "VLAN логически разделяет L2-домены; для безопасной сегментации нужно контролировать межзонный трафик. DMZ — зона публичных сервисов. ACL — правила доступа."], ["VPN и TLS", "VPN создаёт защищённый канал между узлами или сетями в зависимости от технологии. TLS защищает данные в канале и проверяет подлинность стороны при корректной валидации сертификата. TLS не делает приложение автоматически безопасным."], ["Диагностика", "Сначала проверяем DNS и адрес, маршрут, TCP-порт, затем TLS (openssl s_client -connect HOST:PORT -servername HOST), далее приложение и логи. Учитываем NTP, срок действия сертификата и доверенные CA."]], "case": ["TLS-инцидент", "TCP-соединение с коллектором устанавливается, но в логе агента certificate expired. Какое действие обосновано?", ["Заменить парсер", "Проверить срок и цепочку сертификатов, согласовать обновление", "Увеличить EPS", "Отключить валидацию навсегда"], [1], "Ошибка на уровне TLS, не парсинга."], "questions": [{"q": "Имя коллектора разрешается в неправильный IP. Где начать?", "o": ["DNS-записи и настройки резолвера", "Корреляция", "RAM", "Правила EDR"], "a": [0], "e": "Сначала исправляем разрешение имени."}, {"q": "Что выдает DHCP типичному клиенту?", "o": ["Сигнатуры IPS", "Токен PAM", "IP, маску, шлюз и DNS", "Правила SIEM"], "a": [2], "e": "DHCP предоставляет сетевые параметры."}, {"q": "Публикуем внутренний сервер через внешний IP. Какая трансляция типична?", "o": ["SNAT", "DNAT", "NTP", "ARP"], "a": [1], "e": "DNAT меняет адрес назначения."}, {"q": "Какие меры нужны для ограничения доступа из гостевого VLAN к БД?", "o": ["Отдельная зона/VLAN", "Межзонные ACL или МЭ", "Только новый DNS-суффикс", "Только запись в SIEM"], "a": [0, 1], "e": "Логическое разделение дополняется фильтрацией."}, {"q": "Что делает reverse proxy?", "o": ["Обслуживает DHCP", "Выдаёт учётные записи AD", "Хранит резервные копии", "Принимает клиентские запросы от имени внутренних сервисов"], "a": [3], "e": "Reverse proxy расположен перед приложением."}, {"q": "TCP доступен, TLS выдаёт ошибку доверия. Что проверить?", "o": ["Цепочку CA и имя сервера в сертификате", "Количество правил SIEM", "Размер VLAN", "Тип резервной копии"], "a": [0], "e": "Проверяем параметры TLS и доверие."}, {"q": "Какая команда подходит для диагностики TLS?", "o": ["df -h", "openssl s_client", "ip link только", "free -m"], "a": [1], "e": "Показывает TLS-рукопожатие и сертификаты."}, {"q": "Что верно относительно VPN?", "o": ["Он автоматически даёт минимальные привилегии", "Он заменяет EDR", "Он создаёт защищённый канал, но доступ требует отдельных политик", "Он всегда работает через TCP 443"], "a": [2], "e": "VPN не отменяет контроль доступа."}, {"q": "Что обеспечивает NAT сам по себе?", "o": ["Полное обнаружение атак", "Целостность базы", "Проверку приложений", "Трансляцию адресов, а не полноценную политику защиты"], "a": [3], "e": "Фильтрация — отдельная функция."}, {"q": "Источник и коллектор в разных VLAN. Что согласовать для Syslog?", "o": ["Направление, адреса, порт, протокол и правила МЭ", "Только название источника", "Только срок хранения", "Только пароли домена"], "a": [0], "e": "Матрица взаимодействий определяет сетевой доступ."}]}, {"date": "03.12", "title": "Архитектура средств защиты", "tag": "СЗИ", "blocks": [["Сеть", "NGFW контролирует соединения и приложения, IPS обнаруживает и может блокировать атаки; IDS обычно уведомляет. WAF защищает HTTP(S)-приложения; NDR анализирует сетевую телеметрию. Для зашифрованного трафика важна видимость."], ["Хост и доступ", "EPP предотвращает типовые угрозы на устройствах; EDR обнаруживает и реагирует на хостах; XDR связывает несколько доменов телеметрии. IAM/IGA — управление идентичностями и доступом; PAM — привилегированный доступ, хранение/ротация секретов и контроль сессий."], ["Данные и уязвимости", "DLP контролирует каналы утечки; VM выявляет и приоритизирует уязвимости; Sandbox изолированно анализирует подозрительные объекты. Backup обеспечивает восстановление, его необходимо испытывать."], ["Мониторинг", "SIEM собирает, нормализует, хранит и коррелирует события. SOC — люди, процессы, инструменты мониторинга и реагирования; SOAR автоматизирует сценарии, используя интеграции. Не каждый алерт равен подтверждённому инциденту."], ["РП", "Определяем сценарии угроз и требования, выбираем точки контроля, проверяем интеграции и ограничения, планируем пилот и испытания."]], "case": ["Подбери средство", "Публичное веб-приложение получает подозрительные HTTP-запросы. Требуется специализированный контроль запросов с возможностью блокировки.", ["PAM", "WAF", "Backup", "SIEM без интеграций"], [1], "WAF анализирует HTTP(S) в точке, где доступно содержимое."], "questions": [{"q": "Нужно обнаруживать и изолировать заражённую рабочую станцию. Какой класс наиболее прямо решает задачу?", "o": ["DLP", "EDR", "WAF", "VM"], "a": [1], "e": "EDR обнаруживает угрозы и поддерживает реагирование на хосте."}, {"q": "Нужно ограничить административный доступ подрядчиков и записывать их сессии. Что выбрать?", "o": ["PAM", "IDS", "DLP", "WAF"], "a": [0], "e": "PAM управляет привилегированными сессиями."}, {"q": "Нужно выявлять подозрительные соединения между узлами по сетевой телеметрии. Что наиболее подходит?", "o": ["IGA", "Backup", "NDR", "СКУД"], "a": [2], "e": "NDR анализирует сетевую активность."}, {"q": "В чём основное отличие IPS от пассивной IDS?", "o": ["IPS только хранит логи", "IDS всегда расшифровывает TLS", "IPS работает только с БД", "IPS может блокировать трафик согласно политике"], "a": [3], "e": "IPS реализует предотвращение атак."}, {"q": "Какие средства обычно могут поставлять события в SIEM?", "o": ["NGFW", "EDR", "Контроллер домена", "Только сама SIEM"], "a": [0, 1, 2], "e": "SIEM получает телеметрию разных классов."}, {"q": "Какая задача относится к VM?", "o": ["Обнаружение и приоритизация уязвимостей", "Запись привилегированных сессий", "Хранение почты", "Выдача IP"], "a": [0], "e": "VM — vulnerability management."}, {"q": "Какой класс помогает расследовать утечки по контролируемым каналам передачи данных?", "o": ["NTP", "DLP", "DHCP", "PAM только"], "a": [1], "e": "DLP выявляет или предотвращает нарушения политик передачи данных."}, {"q": "SOAR получает алерт. Как безопаснее автоматизировать блокировку критичного сервера?", "o": ["Блокировать любой хост без условий", "Отключить журналирование", "Проверить контекст и предусмотреть согласование", "Удалить все события"], "a": [2], "e": "Критичные действия требуют проверки и согласованных полномочий."}, {"q": "Как подтвердить работоспособность резервной копии?", "o": ["Убедиться, что файл существует", "Проверить только размер", "Проверить наличие лицензии", "Восстановить в изоляции и проверить сервис и данные"], "a": [3], "e": "Только тест восстановления подтверждает практическую пригодность."}, {"q": "Какое утверждение о XDR наиболее точное?", "o": ["Это всегда архив сырых логов", "Это объединённое обнаружение и реагирование по нескольким доменам", "Это синоним VLAN", "Это исключительно сканер уязвимостей"], "a": [1], "e": "XDR связывает данные различных доменов защиты."}]}, {"date": "04.12", "title": "Внедрение и диагностика SIEM", "tag": "SIEM / РП", "blocks": [["Цели и источники", "Сначала бизнес-требования, критичные активы, угрозы и сценарии. Приоритет источников зависит от сценария: AD, VPN, EDR, NGFW, DNS, критичные приложения. Нет универсального первого источника."], ["Архитектура и конвейер", "Источник → агент/служба → транспорт → коллектор → парсинг → нормализация → обогащение → внутренняя маршрутизация → хранение/корреляция → алерт. Операции могут идти параллельно в зависимости от продукта."], ["Сайзинг", "EPS = количество событий / секунды. Сырой объём за сутки = средний EPS × байт/событие × 86400. Хранилище учитывает срок, индексацию/сжатие, копии и запас. Пиковый EPS — для производительности, не вместо среднего. CPU/RAM и лицензии — по требованиям вендора и нагрузочным испытаниям."], ["Диагностика L2", "Локализуем последний исправный участок: локальные логи, служба отправки, сеть, приёмник, парсер, очереди, хранилище, коррелятор, время и права интерфейса. Не перезапускаем сервисы без согласования."], ["Жизненный цикл проекта", "Цели → обследование → требования → сайзинг и архитектура → план и ТЗ → поставка → развертывание → интеграции → контент → испытания (ПМИ) → опытная эксплуатация → обучение → приёмка → сопровождение. Этапы могут пересекаться. HLD/LLD — архитектурные документы, as-built — фактическая реализация, SLA — согласованный уровень обслуживания."]], "case": ["Диагностический квест", "На коллекторе tcpdump видит пакеты, исходные события доступны, но поля user и sourceIP пустые. Где искать причину?", ["Парсер и правила нормализации", "Питание источника", "DNS клиента", "Закупка лицензии"], [0], "Доставка уже подтверждена, нарушена обработка содержимого."], "questions": [{"q": "За минуту поступило 72000 событий. Средний EPS?", "o": ["120", "720", "1200", "72000"], "a": [2], "e": "72000 / 60 = 1200."}, {"q": "Что влияет на сырой суточный объём при неизменном размере события?", "o": ["Средний EPS", "Только пиковый EPS", "Только RAM", "Число аналитиков"], "a": [0], "e": "Объём связан с суммой событий за сутки."}, {"q": "Средний EPS 1000, размер 500 байт. Сколько сырых данных в сутки в десятичных ГБ?", "o": ["4,32", "43,2", "432", "86,4"], "a": [1], "e": "1000 × 500 × 86400 / 10⁹ = 43,2."}, {"q": "Коллектор не получает пакеты, но источник отправляет. Где искать первым?", "o": ["Корреляция", "Права UI", "Парсер", "Сетевой путь и фильтрация"], "a": [3], "e": "Ошибка до приёмника."}, {"q": "Исходный лог есть, но нормализованные поля пусты. Что проверять?", "o": ["Парсинг и маппинг полей", "Только маршрутизацию", "Наличие DNS у пользователя", "Размер монитора"], "a": [0], "e": "Событие дошло, но не разобрано правильно."}, {"q": "События сохраняются, но ожидаемый алерт не появляется. Какие проверки уместны?", "o": ["Условия и включение правила", "Поля событий и временное окно", "Только наличие резервной копии", "Только MAC рабочей станции"], "a": [0, 1], "e": "Проверяем логику обнаружения и входные данные."}, {"q": "Какие данные приоритетны для детекта компрометации доменной учётной записи?", "o": ["События аутентификации AD и VPN", "Только журналы принтеров", "Только температура ЦОД", "Только логи гостевого Wi-Fi"], "a": [0], "e": "Выбор источников следует из сценария."}, {"q": "Что должно определять критерии приёмочных испытаний?", "o": ["Количество вкладок интерфейса", "Согласованные требования и ПМИ", "Личное мнение инженера", "Количество перезагрузок"], "a": [1], "e": "Приёмка должна быть проверяема относительно требований."}, {"q": "Что означает as-built?", "o": ["Предварительная смета", "Модель угроз без архитектуры", "Документация фактически реализованной системы", "Лицензия вендора"], "a": [2], "e": "As-built фиксирует фактическое состояние."}, {"q": "Заказчик добавил 30 источников вне согласованного объёма. Как действует РП?", "o": ["Молча принимает все работы", "Отказывает без анализа", "Подключает их до оценки ресурсов", "Оценивает влияние на сроки, бюджет и нагрузку, согласует изменение"], "a": [3], "e": "Управление изменениями защищает базовые параметры проекта."}]}, {"date": "25.11", "title": "Персональные данные и ИСПДн", "tag": "Комплаенс", "blocks": [["Применимость", "152-ФЗ регулирует обработку ПДн. Оператор определяет цели и состав обработки, проверяет правовые основания, обязанности и меры безопасности. Согласие — не единственное возможное основание. Для конкретной отрасли возможны дополнительные требования."], ["Обследование", "Инвентаризируем данные, цели, субъекты, системы, потоки, места хранения, получателей и доступы. Определяем границы ИСПДн, оценку возможного вреда и актуальные угрозы."], ["Уровни защищённости", "ПП РФ №1119, пп. 5–12: категория данных, тип угроз, сотрудники/прочие субъекты, численность. Тип 1 связан с НДВ системного ПО, тип 2 — прикладного, тип 3 — не связан с НДВ. Категории определяются по п. 5. УЗ-1 строже УЗ-4. Используй калькулятор."], ["Меры и документы", "Для типовой коммерческой ИСПДн состав мер определяется с учётом применимости приказа ФСТЭК №21; при использовании СКЗИ — применимых требований ФСБ. Оформляем решения по УЗ, модель угроз, политику, доступы, регламенты, проект и результаты оценки эффективности."], ["Ответственность", "Оператор отвечает за законность и безопасность обработки; интегратор реализует согласованный объём. РКН контролирует обработку ПДн, ФСТЭК — техническую защиту в пределах компетенции, ФСБ — криптографическую защиту в пределах компетенции. Не всякая ИСПДн требует формальной аттестации."]], "case": ["Учебная ИСПДн", "CRM обрабатывает иные ПДн 5000 клиентов, угрозы 3-го типа обоснованы оператором. Какой уровень следует из п.12б ПП №1119?", ["УЗ-1", "УЗ-2", "УЗ-3", "УЗ-4"], [3], "Для иных ПДн менее 100000 внешних субъектов при угрозах типа 3 — УЗ-4."], "questions": [{"q": "Какая информация нужна до определения УЗ?", "o": ["Категория данных и состав субъектов", "Тип актуальных угроз", "Количество внешних субъектов, когда применимо", "Только бюджет"], "a": [0, 1, 2], "e": "ПП №1119 учитывает эти факторы."}, {"q": "Угрозы типа 1, иные ПДн. Какой УЗ?", "o": ["1", "2", "3", "4"], "a": [0], "e": "П.9а: УЗ-1."}, {"q": "Тип 2, биометрические ПДн в смысле п.5. УЗ?", "o": ["1", "2", "3", "4"], "a": [1], "e": "П.10в: УЗ-2."}, {"q": "Тип 3, специальные ПДн 120000 внешних субъектов. УЗ?", "o": ["1", "2", "3", "4"], "a": [1], "e": "П.10е: УЗ-2."}, {"q": "Что характеризует угрозы типа 2?", "o": ["НДВ прикладного ПО", "Только сетевые атаки", "НДВ системного ПО как тип 1", "Количество субъектов"], "a": [0], "e": "Тип 2 связан с недекларированными возможностями прикладного ПО."}, {"q": "Кто определяет актуальный тип угроз для ИСПДн?", "o": ["Поставщик лицензии единолично", "Оператор с учётом оценки вреда и применимых актов", "Любой пользователь", "Только производитель сервера"], "a": [1], "e": "П.7 ПП №1119 возлагает определение на оператора."}, {"q": "Что означает покупка SIEM для соответствия 152-ФЗ?", "o": ["Автоматическое полное соответствие", "Отсутствие необходимости в документах", "Возможность реализовать часть необходимых мер", "Автоматическая аттестация"], "a": [2], "e": "Средство реализует часть мер, не весь комплекс обязанностей."}, {"q": "Что из перечисленного относится к обследованию ИСПДн?", "o": ["Границы и потоки данных", "Цели и правовые основания", "Категории данных", "Только выбор вендора"], "a": [0, 1, 2], "e": "Обследование определяет контекст обработки."}, {"q": "Кто сохраняет обязанности оператора после договора с интегратором?", "o": ["Только вендор", "Только инженер", "Никто", "Оператор"], "a": [3], "e": "Договор не снимает обязанности оператора."}, {"q": "Как корректно отнестись к ровно 100000 внешних субъектов, если пункт использует «более» и «менее»?", "o": ["Всегда автоматически УЗ-4", "Проверить применимые пункты и получить обоснованное решение", "Округлить до 99999", "Не учитывать численность"], "a": [1], "e": "Пограничное значение требует анализа формулировок."}], "sources": [["152-ФЗ", "https://www.consultant.ru/document/cons_doc_LAW_61801/"], ["ПП 1119", "https://base.garant.ru/70252506/"], ["Приказ 21", "https://www.consultant.ru/document/cons_doc_LAW_146520/"]]}, {"date": "29.11", "title": "Управление проектом ИБ", "tag": "РП", "blocks": [["Инициация и план", "Фиксируем цели, стейкхолдеров, границы, критерии успеха. WBS декомпозирует работы. План определяет зависимости, ресурсы, сроки, бюджет и риски. RACI распределяет ответственность."], ["Контракт и изменения", "Waterfall удобен при стабильных требованиях и формальной приёмке; итерационный подход — при уточняемом контенте. Реальный проект может быть гибридным. Изменения объёма оцениваются и согласуются уполномоченными сторонами."], ["Управление рисками проекта", "Риск проекта — неопределённость, влияющая на цели проекта. Например, задержка доступов сдвигает сроки. Назначаем владельца, меры, триггеры и контролируем статус. Отличаем риск от уже возникшей проблемы."], ["Документы", "ТЗ фиксирует требования, HLD/LLD описывают архитектуру, ПМИ задаёт проверки, протоколы фиксируют результаты, as-built описывает реализацию, SLA — уровень обслуживания. Требования должны иметь критерии проверки."], ["Завершение", "Устраняем замечания, согласуем остаточные риски в рамках полномочий, обучаем пользователей, передаём документацию и эксплуатацию, подписываем акты по договору."]], "case": ["Срыв срока", "До приёмки осталось 5 дней, заказчик задерживает сетевые доступы. Что делает РП?", ["Фиксирует проблему и влияние, эскалирует владельцу, согласует план восстановления", "Скрывает задержку", "Завершает испытания без доступа", "Меняет ТЗ единолично"], [0], "Управляем проблемой прозрачно и согласуем действия."], "questions": [{"q": "Что относится к WBS?", "o": ["Декомпозиция работ", "Список CVE", "Правила NGFW", "Шифрование копий"], "a": [0], "e": "WBS структурирует объём проекта."}, {"q": "Что отличает риск проекта от проблемы?", "o": ["Риск всегда связан с атакой", "Проблема уже возникла, риск ещё неопределён", "Проблема не требует действий", "Риск всегда равен нулю"], "a": [1], "e": "Проблема — реализовавшееся обстоятельство."}, {"q": "Заказчик меняет требования. Что делать сначала?", "o": ["Сразу подписать акт", "Игнорировать запрос", "Оценить влияние изменения и согласовать его", "Перенести ответственность на инженера"], "a": [2], "e": "Управление изменениями сохраняет контроль сроков и объёма."}, {"q": "Какой документ задаёт методы проверки требований?", "o": ["RACI", "SLA", "HLD", "ПМИ"], "a": [3], "e": "ПМИ определяет испытания."}, {"q": "Для чего используется RACI?", "o": ["Распределить роли и ответственность", "Посчитать EPS", "Определить тип угроз", "Выбрать VLAN"], "a": [0], "e": "RACI — матрица ответственности."}, {"q": "Какие признаки полезны для критерия приёмки SIEM?", "o": ["Измеримость", "Связь с требованиями", "Формулировка «всё работает» без проверки", "Определённый способ проверки"], "a": [0, 1, 3], "e": "Проверяемость и связь с ТЗ обязательны для ясной приёмки."}, {"q": "Что лучше делать при фиксированном контракте и уточняемом контенте корреляции?", "o": ["Всегда исключить итерации", "Согласовать фиксированные рамки и итеративную настройку внутри них", "Изменять сроки без согласования", "Не вести документацию"], "a": [1], "e": "Гибридный подход может сочетать формальную приёмку и итерации."}, {"q": "Какой документ описывает реально установленную архитектуру?", "o": ["ТКП", "Матрица угроз", "As-built", "Устав проекта"], "a": [2], "e": "As-built фиксирует реализованное решение."}, {"q": "Что подтверждает завершение проекта в договорном контексте?", "o": ["Только факт установки ПО", "Только письмо инженера", "Только число событий", "Согласованные результаты испытаний и предусмотренные договором документы"], "a": [3], "e": "Завершение определяется критериями договора."}, {"q": "Кто должен утверждать принятие остаточного риска организации?", "o": ["Уполномоченный владелец риска/руководство", "Любой подрядчик", "Стажёр", "SIEM автоматически"], "a": [0], "e": "Принятие риска требует полномочий."}]}, {"date": "24.11", "title": "Комплаенс: карта законодательства и регуляторов", "tag": "Комплаенс", "blocks": [["Цель урока", "Комплаенс — соблюдение применимых обязательных требований и принятых обязательств. Для РП важно установить область применимости до выбора продукта. Законы определяют обязанности, подзаконные акты конкретизируют требования, методики помогают их реализовать. Стандарт не автоматически обязателен: проверяй закон, договор и сферу применения."], ["149-ФЗ — базовый закон", "Регулирует отношения с информацией, ИТ и защитой информации. Ст. 16 задаёт общие направления защиты, включая предотвращение неправомерного доступа и обеспечение возможности восстановления. Это не перечень обязательных продуктов."], ["152-ФЗ — персональные данные", "Определяет правила обработки ПДн, основания, права субъектов и обязанности оператора. Ст. 18.1 — организация обработки, ст. 19 — безопасность, ст. 22 — уведомление регулятора с предусмотренными исключениями. Для автоматизированной обработки анализируем ПП №1119 и применимые меры ФСТЭК №21; при применении криптографии — требования ФСБ."], ["187-ФЗ — КИИ", "Регулирует безопасность критической информационной инфраструктуры в определённых законом сферах. Сначала проверяем субъект и объекты КИИ, затем категорирование по действующим правилам. Приказ №235 — создание и функционирование систем безопасности значимых объектов; №239 — требования к их безопасности."], ["Государственные системы", "Приказ ФСТЭК №117 действует с 01.03.2026 и заменил №17; его область включает ГИС и иные ИС перечисленных в приказе организаций. Проверяем область применения и актуальную редакцию, а также специальные требования к ПДн и криптографии, если применимы."], ["Кто регулирует", "Роскомнадзор — контроль обработки ПДн. ФСТЭК — техническая защита информации и безопасность КИИ в рамках полномочий. ФСБ — криптографическая защита и ГосСОПКА в рамках полномочий. Банк России устанавливает отраслевые требования для поднадзорных организаций. Интегратор не заменяет владельца обязанностей."], ["Рабочий инструмент РП", "Создаём матрицу: система → данные → статус организации → применимый документ и пункт → требование → мера → ответственный → доказательство. Пример: CRM с ПДн → 152-ФЗ, ст.19 → определить угрозы → модель угроз. Не закупаем SIEM только по номеру закона."], ["Как заниматься", "15 минут: прочитать карту законов и открыть статьи 16, 19 и 2 по ссылкам ниже. 10 минут: пройти практику и объяснить, какие факты нужны для вывода. 10 минут: тест. 10 минут: повторить ошибки и записать три главных различия законов."]], "case": ["Первый день у заказчика", "Частный интернет-магазин хранит ФИО и телефоны клиентов. Фактов о КИИ или статусе ГИС нет. Какую работу начинаешь?", ["Проверить 152-ФЗ, 149-ФЗ, состав ИСПДн и применимость подзаконных требований", "Присвоить КИИ категорию 1 без обследования", "Применить №117 только потому, что сайт доступен из интернета", "Заказать сертифицированную SIEM, считая вопрос закрытым"], [0], "Обработка ПДн указывает на необходимость анализа 152-ФЗ. Остальные режимы требуют отдельных оснований."], "questions": [{"q": "Компания хранит данные клиентов, но не относится к сферам КИИ по имеющимся данным. Что проверять прежде всего?", "o": ["152-ФЗ и применимые требования защиты ПДн", "187-ФЗ как единственный режим", "Приказ 117 для любого сайта", "Только ГОСТ по договору"], "a": [0], "e": "Применимость определяется данными и статусом системы."}, {"q": "В госсистеме обрабатываются ПДн. Как строить реестр требований?", "o": ["Только 152-ФЗ", "Только приказ 117", "Проверить требования обоих режимов и их совместное применение", "Выбрать документ с наибольшим номером"], "a": [2], "e": "Режимы могут действовать совместно."}, {"q": "Заказчик хочет понять общий правовой режим защиты информации. Какой документ изучить первым?", "o": ["ПП 1119", "Приказ 239", "Приказ 21", "149-ФЗ, в частности ст.16"], "a": [3], "e": "149-ФЗ задаёт общие правовые основы защиты информации."}, {"q": "Какое соответствие документов верно?", "o": ["1119 — меры для значимых КИИ", "1119 — уровни защиты ПДн, 21 — меры защиты ИСПДн", "21 — категорирование КИИ", "235 — уровни ПДн"], "a": [1], "e": "Постановление определяет уровни, приказ конкретизирует меры."}, {"q": "Какой орган прежде всего контролирует соблюдение требований обработки ПДн?", "o": ["Роскомнадзор", "ФСТЭК", "Банк России", "Минцифры"], "a": [0], "e": "РКН — уполномоченный орган по защите прав субъектов ПДн."}, {"q": "Какой подход к ГОСТ или ISO наиболее корректен?", "o": ["Любой стандарт обязателен", "Стандарт всегда доброволен даже при договоре", "Проверить основания обязательности, включая договор и нормативную ссылку", "Игнорировать стандарт, если есть ФЗ"], "a": [2], "e": "Обязательность зависит от применимости и основания."}, {"q": "Что необходимо установить перед применением 187-ФЗ к конкретной системе?", "o": ["Наличие SIEM", "Число событий EPS", "Наличие интернет-доступа", "Статус субъекта, сферу деятельности и принадлежность объекта"], "a": [3], "e": "Это первичная проверка применимости режима КИИ."}, {"q": "Какой результат обследования полезнее для РП?", "o": ["Список продуктов без требований", "Матрица применимости с ответственными и доказательствами", "Список законов без связи с системами", "Каталог всех сертифицированных СЗИ"], "a": [1], "e": "Матрица связывает требования с реализацией и проверкой."}, {"q": "Какие два утверждения верны? Выбери все верные.", "o": ["Приказ 235 относится к системам безопасности значимых КИИ", "Приказ 239 относится к безопасности значимых объектов КИИ", "Приказ 117 применяется к любой частной CRM без проверки", "Интегратор автоматически становится оператором ПДн"], "a": [0, 1], "e": "235 и 239 регулируют связанные, но разные аспекты защиты значимых объектов."}, {"q": "Заказчик ссылается только на старый приказ 17 в новом проекте ГИС в ноябре 2026. Что сделать?", "o": ["Оставить без проверки", "Использовать 17 как единственный документ", "Проверить действующий приказ 117, переходные и специальные требования", "Заменить все требования на ISO 27001"], "a": [2], "e": "Приказ 117 вступил в силу 1 марта 2026, требуется актуальная проверка."}], "diagram": ["Организация", "Системы и данные", "Применимость", "Требования", "Доказательства"], "sources": [["149-ФЗ", "https://www.consultant.ru/document/cons_doc_LAW_61798/"], ["152-ФЗ", "https://www.consultant.ru/document/cons_doc_LAW_61801/"], ["187-ФЗ", "https://www.consultant.ru/document/cons_doc_LAW_220885/"], ["Приказ 117", "https://www.consultant.ru/document/cons_doc_LAW_507869/"], ["ПП 1119", "https://base.garant.ru/70252506/"], ["Приказ 21", "https://www.consultant.ru/document/cons_doc_LAW_146520/"]]}, {"date": "26.11", "title": "КИИ: 187-ФЗ и категорирование", "tag": "Комплаенс", "blocks": [["Применимость", "КИИ — информационные системы, сети и АСУ субъектов КИИ в сферах, перечисленных в статье 2 закона. Не любая важная система является объектом КИИ. Проверяем право владения, отрасль и назначение системы."], ["Категорирование", "Цель — определить значимость объекта по действующим правилам категорирования и показателям последствий. Категории 1, 2 и 3; 1 наиболее высокая. Возможен вывод об отсутствии категории. Нельзя присваивать категорию только по цене оборудования или объёму логов. В 2026 менялись правила, проверять применимую отраслевую редакцию и сроки отдельно."], ["Значимый объект", "Значимый объект — объект с присвоенной категорией и включением в реестр значимых объектов. Ст.10 — создание системы безопасности, ст.11 — требования безопасности. Приказ 235 описывает создание и функционирование системы безопасности; 239 — требования к обеспечению безопасности."], ["Реагирование", "ГосСОПКА — государственная система обнаружения, предупреждения и ликвидации последствий компьютерных атак. Проверяем обязанности по взаимодействию и информированию по действующим нормам, не сводим их только к покупке SIEM."], ["Артефакты РП", "Перечень объектов, материалы категорирования, сведения об объектах, модель угроз, требования к системе безопасности, план внедрения, документы эксплуатации и испытаний. Конкретный состав зависит от статуса, отрасли и редакции норм."], ["Системы безопасности", "Приказ № 235 регулирует создание и функционирование систем безопасности значимых объектов КИИ; приказ № 239 — требования к безопасности значимых объектов. Проверяй редакции и сроки вступления изменений в силу."]], "case": ["Энергетический заказчик", "Энергокомпания просит назвать категорию своей АСУ ТП по числу серверов. Что делать?", ["Присвоить 1", "Присвоить 3", "Оценить последствия нарушения работы объекта по применимым критериям", "Использовать уровень защищённости ПДн"], [2], "Категорирование КИИ опирается на установленные показатели значимости, а не на число серверов."], "questions": [{"q": "Как определить применимость 187-ФЗ?", "o": ["По наличию ПДн", "По статусу субъекта, отрасли и объекту", "По размеру компании", "По факту покупки SIEM"], "a": [1], "e": "Применимость вытекает из определения субъекта и объекта."}, {"q": "Объект не получил категорию. Что это означает?", "o": ["Любые обязанности исчезли", "Объект автоматически перестаёт быть КИИ", "Нужно проверить сохраняющиеся обязанности субъекта", "Нужно присвоить УЗ-4"], "a": [2], "e": "Отсутствие категории не снимает автоматически все обязанности субъекта."}, {"q": "Какая категория значимости наиболее высокая?", "o": ["1", "2", "3", "4"], "a": [0], "e": "Категория 1 — наиболее высокая."}, {"q": "Что регулирует приказ 235?", "o": ["ПДн и согласия", "Классификацию ГИС", "Лицензирование SIEM", "Создание и функционирование систем безопасности значимых объектов"], "a": [3], "e": "Это предмет приказа 235."}, {"q": "Что регулирует приказ 239?", "o": ["Требования безопасности значимых объектов", "Срок хранения всех логов в РФ", "Только криптографию", "Правила получения согласия"], "a": [0], "e": "239 устанавливает требования к безопасности значимых КИИ."}, {"q": "На объекте КИИ обрабатываются ПДн. Что делать?", "o": ["Выбрать только 187-ФЗ", "Выбрать только 152-ФЗ", "Проверить оба режима и их применимость", "Применить только ISO"], "a": [2], "e": "Режимы могут пересекаться."}, {"q": "Что является основанием для категорирования?", "o": ["Пиковый EPS", "Последствия нарушения функционирования по критериям", "Число администраторов", "Вендор оборудования"], "a": [1], "e": "Категория зависит от критериев значимости."}, {"q": "Что из перечисленного относится к ГосСОПКА?", "o": ["Система выдачи сертификатов СЗИ", "Каталог средств защиты", "Реестр согласий ПДн", "Обнаружение, предупреждение и ликвидация последствий компьютерных атак"], "a": [3], "e": "Это назначение ГосСОПКА."}, {"q": "Заказчик требует внедрить СЗИ до выяснения границ объекта. Как поступить?", "o": ["Зафиксировать риск и согласовать обследование и границы", "Купить максимальный комплект", "Определить категорию по названию отрасли", "Подписать испытания заранее"], "a": [0], "e": "Границы и требования нужны для обоснования проекта."}, {"q": "Выбери необходимые для проекта сведения.", "o": ["Границы объекта", "Применимые требования и статус значимости", "Критичные функции и последствия отказа", "Только цвет интерфейса SIEM"], "a": [0, 1, 2], "e": "Эти сведения определяют архитектуру и критерии приёмки."}], "diagram": ["Субъект", "Объект", "Критерии", "Категория", "Система безопасности"], "sources": [["187-ФЗ", "https://www.consultant.ru/document/cons_doc_LAW_220885/"], ["Приказ 239", "https://www.consultant.ru/document/cons_doc_LAW_294287/"], ["НКЦКИ", "https://www.cert.gov.ru/"], ["Приказ ФСТЭК № 235", "https://base.garant.ru/71886248/"]]}, {"date": "27.11", "title": "ГИС, приказ 117, сертификация и аттестация", "tag": "Комплаенс", "blocks": [["Область действия", "Приказ ФСТЭК №117 от 11.04.2025 вступил в силу 01.03.2026. Он регулирует защиту информации в ГИС и иных ИС государственных органов, государственных унитарных предприятий и государственных учреждений в пределах установленной области. Не считать любой веб-сервис ГИС."], ["Классификация и защита", "Определяем статус и границы системы, виды информации, негативные последствия, класс защищённости и применимые требования по действующему тексту. Если обрабатываются ПДн, проверяем совместную применимость ПП 1119 и приказа 117."], ["Сертификация", "Сертификация средства защиты подтверждает его соответствие определённым требованиям в рамках сертификата: проверяем версию, конфигурацию, срок и условия применения. Наличие сертификата на продукт не означает соответствие всей системы."], ["Аттестация", "Аттестация объекта информатизации — процедура подтверждения соответствия объекта требованиям защиты в установленных случаях. Отличается от сертификации продукта и от обычных приёмочных испытаний. Требования и порядок зависят от режима системы."], ["Проектный результат", "Матрица требований, проект защиты, перечень и параметры СЗИ, эксплуатационные регламенты, результаты испытаний, документы оценки соответствия. Уточняем, кто вправе проводить работы и какие лицензии необходимы."], ["Актуализация на 24.11.2026", "Приказ № 117 вступил в силу 01.03.2026; изменения приказом № 137 от 08.05.2026 применяются с 01.09.2026. Сверяй редакцию и переходные положения перед проектом."]], "case": ["Сертификат не равен аттестации", "Заказчик утверждает, что покупка сертифицированного NGFW автоматически означает аттестацию ГИС. Твой ответ?", ["Согласиться", "Проверить требования к объекту и отдельно провести требуемую оценку соответствия", "Проверить только EPS", "Запросить согласия сотрудников"], [1], "Сертификат относится к средству защиты, аттестация — к объекту и его требованиям."], "questions": [{"q": "Какой документ заменил приказ 17 с 01.03.2026?", "o": ["Приказ 21", "Приказ 239", "Приказ 117", "ПП 1119"], "a": [2], "e": "117 вступил в силу 1 марта 2026."}, {"q": "Частная CRM доступна из интернета. Можно ли только по этому факту считать её ГИС?", "o": ["Нет, необходимо проверить правовой статус и назначение", "Да, если есть ПДн", "Да, если есть HTTPS", "Да, если система в облаке"], "a": [0], "e": "Интернет-доступ не определяет статус ГИС."}, {"q": "Что подтверждает сертификат на СЗИ?", "o": ["Соответствие всей организации", "Отсутствие любых угроз", "Успешную приёмку проекта", "Соответствие средства в установленных границах сертификата"], "a": [3], "e": "Сертификат имеет определённые область и условия."}, {"q": "Что такое аттестация объекта?", "o": ["Сканирование единственного сервера", "Подтверждение соответствия объекта требованиям защиты в установленном порядке", "Согласие на обработку ПДн", "Подбор лицензий по EPS"], "a": [1], "e": "Аттестация относится к объекту и его требованиям."}, {"q": "Система обрабатывает ПДн и подпадает под 117. Как действовать?", "o": ["Учесть совместно применимые требования", "Игнорировать 1119", "Считать сертификат заменой модели угроз", "Применять только 187-ФЗ"], "a": [0], "e": "Режимы защиты могут применяться совместно."}, {"q": "При покупке сертифицированного продукта что проверять?", "o": ["Лишь производителя", "Лишь цену", "Версию, условия и область сертификата", "Только размер базы"], "a": [2], "e": "Важны границы подтверждённого соответствия."}, {"q": "Чем ПМИ отличается от сертификата?", "o": ["Оба подтверждают одно и то же", "ПМИ описывает порядок испытаний проекта, сертификат относится к подтверждённому соответствию продукта", "ПМИ выдаёт только регулятор", "Сертификат содержит график проекта"], "a": [1], "e": "ПМИ используется для проверки требований проекта."}, {"q": "На что опираться при выборе класса защищённости ГИС?", "o": ["EPS", "Количество VLAN", "УЗ любой соседней ИСПДн", "Применимые критерии приказа и характеристики системы"], "a": [3], "e": "Класс определяется по требованиям конкретного режима."}, {"q": "Выбери два полезных доказательства реализации меры.", "o": ["Протокол проверки доступа", "Конфигурация с подтверждением применённой политики", "Рекламный буклет", "Устное обещание поставщика"], "a": [0, 1], "e": "Доказательства должны показывать фактическую реализацию и проверку."}, {"q": "В проекте изменился состав системы. Что сделать?", "o": ["Игнорировать после закупки", "Оценить влияние на границы, угрозы и требования, согласовать изменение", "Автоматически повысить класс", "Удалить документацию"], "a": [1], "e": "Изменение состава может повлиять на применимость и проект."}], "diagram": ["Статус системы", "Класс", "Требования", "Проект", "Оценка"], "sources": [["Приказ 117", "https://www.consultant.ru/document/cons_doc_LAW_507869/"], ["149-ФЗ, ст.16", "https://www.consultant.ru/document/cons_doc_LAW_61798/0e9ec16b786dcbdaaa7f44abfc4a15e601d5be22/"]]}, {"date": "28.11", "title": "Модель угроз и матрица требований", "tag": "Комплаенс", "blocks": [["Модель угроз", "Модель угроз описывает актуальные угрозы в контексте конкретной системы. Методика ФСТЭК от 05.02.2021 предусматривает анализ негативных последствий, объектов воздействия, нарушителей, способов реализации и актуальности угроз. БДУ — источник сведений, а не готовая модель."], ["Обследование", "Нужны архитектура, границы, потоки данных, внешние интерфейсы, роли, полномочия, состав ПО и существующие меры. Без этого трудно обосновать актуальность угроз."], ["Связь с мерами", "Пример: критичная CRM, внешняя точка доступа, риск компрометации учётных данных. Меры: MFA и ограничение прав, регистрация входов, обнаружение подозрительных событий. Проверяем, что меры соответствуют применимым нормативным требованиям."], ["Документация", "Ведём матрицу: источник требования, идентификатор, формулировка, система, мера, ответственный, способ проверки, статус. Для проекта SIEM: требование регистрации событий → перечень событий → интеграция → проверка поступления, нормализации, хранения."], ["Риск и комплаенс", "Риск помогает приоритизировать, но не отменяет обязательную меру. Снижение, избегание, передача и принятие — четыре подхода обработки риска. Остаточный риск согласует уполномоченный владелец."]], "case": ["Аудитор проверяет мониторинг", "Есть лицензия SIEM, но нет логов контроллеров домена. Как доказать выполнение требования регистрации нужных событий?", ["Показать счёт за лицензию", "Проверить согласованный перечень событий, подключение, поиск и протокол испытаний", "Показать рекламный буклет", "Считать требование выполненным по факту установки"], [1], "Доказательство должно подтверждать работу меры, а не факт приобретения."], "questions": [{"q": "Как использовать БДУ ФСТЭК?", "o": ["Скопировать все угрозы без анализа", "Считать его готовым сертификатом", "Использовать как источник для оценки угроз конкретной системы", "Использовать вместо обследования"], "a": [2], "e": "БДУ служит источником сведений, требующим анализа контекста."}, {"q": "Что нужно для модели угроз?", "o": ["Границы, архитектура, нарушители, последствия и способы реализации", "Только версия SIEM", "Только список сотрудников", "Только смета"], "a": [0], "e": "Модель учитывает конкретную систему и возможные последствия."}, {"q": "Что означает остаточный риск?", "o": ["Любая угроза до мер", "Число ошибок аудита", "Стоимость проекта", "Риск после учёта действующих мер"], "a": [3], "e": "Остаточный риск сохраняется после мер."}, {"q": "Какой способ обработки риска реализует отказ от рискованной деятельности?", "o": ["Передача", "Избегание", "Принятие", "Снижение"], "a": [1], "e": "Избегание прекращает деятельность, создающую риск."}, {"q": "Компания страхует часть потерь, сохраняя систему. Какой подход?", "o": ["Передача", "Избегание", "Принятие", "Обнаружение"], "a": [0], "e": "Страхование передаёт часть финансовых последствий."}, {"q": "Обязательная мера неудобна. Владелец риска предлагает её не выполнять. Что делать?", "o": ["Принять риск и забыть о законе", "Удалить требование из ТЗ", "Проверить допустимые способы выполнения и эскалировать несоответствие", "Отменить аудит"], "a": [2], "e": "Принятие риска не отменяет обязательные нормы."}, {"q": "Как связать требование регистрации событий с SIEM?", "o": ["Указать только название вендора", "Определить события, источники, настройки и испытания", "Подписать акт до подключения", "Выбрать только объём диска"], "a": [1], "e": "Связь требования и доказательства делает меру проверяемой."}, {"q": "Какие сведения подтверждают применимость угрозы? Выбери все верные.", "o": ["Доступные нарушителю интерфейсы", "Возможные негативные последствия", "Способы реализации угрозы в конкретной системе", "Только число лицензий SIEM"], "a": [0, 1, 2], "e": "Эти сведения позволяют оценить угрозу в контексте системы."}, {"q": "После изменения архитектуры что делать с моделью угроз?", "o": ["Хранить без пересмотра", "Удалить", "Заменить перечнем СЗИ", "Проверить актуальность и обновить при необходимости"], "a": [3], "e": "Модель должна соответствовать действующей архитектуре."}, {"q": "Какой элемент матрицы требований наиболее полезен для приёмки?", "o": ["Цвет статуса", "Проверяемый критерий и доказательство выполнения", "Имя продавца", "Размер презентации"], "a": [1], "e": "Приёмка требует проверяемых результатов."}], "diagram": ["Последствия", "Объекты воздействия", "Нарушители", "Актуальные угрозы", "Меры", "Доказательства"], "sources": [["Методика ФСТЭК 2021", "https://www.consultant.ru/document/cons_doc_LAW_378330/"], ["БДУ ФСТЭК", "https://bdu.fstec.ru/"]]}, {"date": "05.12", "title": "Windows: журналы и аудит", "tag": "Windows", "blocks": [["Журналирование", "Windows Event Log хранит события по каналам. Security отражает аудит безопасности при включённых политиках; System — состояние ОС и служб; Application — прикладные события. События должны собираться с нужных узлов, а не только с контроллеров домена."], ["Аутентификация", "4624 — успешный вход; 4625 — неуспешный; 4672 — специальные привилегии при входе. Не всякий успешный вход после ошибок означает компрометацию: учитывай Logon Type, адрес, пользователя, время и бизнес-контекст."], ["Процессы", "4688 — создание процесса при соответствующей политике аудита. Sysmon может добавлять телеметрию процессов, соединений и файлов по своей конфигурации. PID сам по себе не уникален во времени; связывай с узлом, временем и идентификатором процесса."], ["Практика инженера", "Get-WinEvent -LogName Security -MaxEvents 20 позволяет посмотреть локальный журнал при наличии прав. WEF передаёт события по подписке. Если данные пропали, проверь аудит, журнал, подписку, сеть, коллектор и диапазон времени в SIEM."], ["Приёмка", "В матрице тестов зафиксируй узел, событие, ожидаемые нормализованные поля и допустимую задержку. Проверяй полноту журналов и синхронизацию времени; не включай избыточный сбор без сайзинга."]], "diagram": ["Пользователь", "Windows", "Security / Sysmon", "коллектор", "SIEM"], "case": ["Контрольная интеграция Windows", "В журнале Security есть контрольное событие, но в SIEM оно не найдено. Как локализовать проблему?", ["Проверить подписку, доставку, коллектор и фильтр поиска", "Переустановить AD", "Отключить аудит", "Увеличить диски до проверки"], [0], "Начни с последнего подтверждённого исправного участка и проверяй цепочку."], "questions": [{"q": "Событие 4625 появилось на контроллере домена. Что можно утверждать?", "o": ["Зафиксирована неудачная попытка входа", "Пароль точно украден", "Пользователь точно заблокирован", "Создан новый пользователь"], "a": [0], "e": "4625 отражает неудачный вход, но не доказывает атаку."}, {"q": "После серии 4625 пришло 4624. Что сделать?", "o": ["Проверить пользователя, узел, источник и тип входа", "Автоматически признать взлом", "Удалить журнал", "Признать события ложными"], "a": [0], "e": "Контекст необходим для вывода."}, {"q": "В SIEM нет 4688 и локально тоже. Первый шаг?", "o": ["Проверить политику аудита создания процессов", "Увеличить хранилище SIEM", "Перезапустить коррелятор", "Сменить правило маршрутизации SIEM"], "a": [0], "e": "Сначала проверяется генерация события."}, {"q": "Какая телеметрия нужна для анализа родительского процесса?", "o": ["События создания процессов с идентификаторами и временем", "Только журнал DNS", "Только события блокировки учёток", "Только журнал резервного копирования"], "a": [0], "e": "Процессная телеметрия позволяет построить дерево процессов."}, {"q": "События есть локально, но WEF не передаёт. Что проверять?", "o": ["Подписку, службу и связность WEF", "Модель риска", "Только корреляцию", "Тип лицензии DLP"], "a": [0], "e": "Проблема находится в доставке."}, {"q": "Два узла имеют различное время. Чем это опасно?", "o": ["Ошибочной последовательностью событий при корреляции", "Обязательной потерей всех событий", "Изменением пароля домена", "Отсутствием TCP-соединения"], "a": [0], "e": "Несинхронность искажает временные связи."}, {"q": "Что означает 4672?", "o": ["Специальные привилегии назначены при входе", "Любая смена пароля", "Удаление файла", "Запуск WEF"], "a": [0], "e": "Это контекст привилегированного входа."}, {"q": "Что включить в тест приёмки Windows-аудита?", "o": ["Контрольное событие, поля, узел и задержку", "Только снимок интерфейса", "Только объём ОЗУ", "Только наличие лицензии"], "a": [0], "e": "Проверка должна подтверждать фактический сбор."}, {"q": "Как уменьшить шум без потери нужной телеметрии?", "o": ["Определить сценарии и проверить фильтры на тестах", "Удалить все успешные входы", "Хранить только ошибки ОС", "Отключить аудит процессов всегда"], "a": [0], "e": "Фильтры зависят от задач обнаружения."}, {"q": "Зачем Security и System собирать отдельно?", "o": ["Они отражают разные категории событий", "Оба всегда одинаковы", "System заменяет аудит входов", "Security содержит все сетевые пакеты"], "a": [0], "e": "Каналы имеют разные назначения."}]}, {"date": "06.12", "title": "Linux: службы, права и логи", "tag": "Linux", "blocks": [["Права", "В Linux права rwx определяют чтение, запись и выполнение для владельца, группы и остальных. sudo делегирует разрешённые административные действия. Не стоит устранять ошибки доступа выдачей 777: это увеличивает поверхность риска."], ["Службы", "systemctl status показывает состояние службы, journalctl -u имя — журнал конкретного unit. Запущенная служба не доказывает, что она успешно обрабатывает данные; проверь ошибки и очереди."], ["Сеть и ресурсы", "ss -lntup показывает слушающие сокеты; df -h — занятое дисковое пространство; df -i — inode; free -m — память. tcpdump на разрешённом тестовом стенде показывает факт передачи пакетов."], ["Доставка", "journald может хранить события в памяти или на диске в зависимости от конфигурации. rsyslog может отправлять события на коллектор; TCP и TLS требуют совместимых настроек на обеих сторонах."], ["Приёмка", "Документируй service account, минимальные права, расписание, ротацию логов, резервирование и мониторинг. Контрольное событие должно пройти от источника до поиска в SIEM."]], "diagram": ["Процесс", "systemd / journald", "rsyslog", "сеть", "SIEM"], "case": ["Linux: потеря логов", "Служба коллектора работает, но диск заполнен на 100%. Что предпринять?", ["Согласованно освободить или расширить хранилище, проверить очередь и потери", "Удалить все журналы без согласования", "Изменить пароль пользователя", "Изменить VLAN"], [0], "Исправь причину нехватки места, сохрани доказательства и проверь восстановление потока."], "questions": [{"q": "Служба rsyslog запущена, но событий нет. Что лучше?", "o": ["Изучить её журнал и параметры отправки", "Считать доставку исправной", "Сразу выдать 777 на /var/log", "Поменять SIEM"], "a": [0], "e": "Статус running не подтверждает успешную доставку."}, {"q": "Как посмотреть журнал конкретной systemd-службы?", "o": ["journalctl -u имя", "df -h", "ss -lntup", "free -m"], "a": [0], "e": "journalctl фильтрует события по unit."}, {"q": "Что показывает ss -lntup?", "o": ["Слушающие TCP/UDP-сокеты и процессы при наличии прав", "Размер базы SIEM", "Правила корреляции", "Права файлов"], "a": [0], "e": "Сокеты помогают проверить приёмник."}, {"q": "Файловая система имеет место, но файлы не создаются. Дополнительная проверка?", "o": ["df -i", "ping", "whoami", "uname -r"], "a": [0], "e": "Могут закончиться inode."}, {"q": "Сервису нужны только права чтения лога. Что выбрать?", "o": ["Минимально необходимые права на конкретный журнал", "root без ограничений", "777 для всех", "Отключить ACL"], "a": [0], "e": "Минимальные привилегии снижают последствия компрометации."}, {"q": "Что проверить при TLS-сбое доставки?", "o": ["Доверие сертификатам, имя, время и настройки TLS", "Только объём диска", "Только парсер", "Только правило SIEM"], "a": [0], "e": "TLS зависит от согласованных параметров и доверия."}, {"q": "В журнале источник пишет ошибку отправки connection refused. Что дальше?", "o": ["Проверить доступность порта и слушатель получателя", "Сразу исправлять парсер", "Увеличить retention", "Удалить события"], "a": [0], "e": "Отказ TCP часто связан с приёмом или сетевой политикой."}, {"q": "Зачем нужна ротация логов?", "o": ["Ограничивать рост и управлять хранением", "Заменять резервное копирование", "Обеспечивать аутентификацию", "Синхронизировать время"], "a": [0], "e": "Ротация управляет файлами журналов."}, {"q": "Что проверяет df -h?", "o": ["Использование файловых систем", "Потребление CPU процессом", "Состояние TLS", "Журнал аутентификации"], "a": [0], "e": "Это проверка дискового пространства."}, {"q": "Как доказать интеграцию?", "o": ["Сгенерировать разрешённое контрольное событие и найти его поля в SIEM", "Проверить только ping", "Проверить только запущенную службу", "Сделать скриншот коллектора"], "a": [0], "e": "Тест подтверждает весь путь события."}]}, {"date": "07.12", "title": "AD, Kerberos, LDAP и GPO", "tag": "Identity", "blocks": [["AD DS", "Служба каталогов хранит объекты домена: пользователей, компьютеры, группы и OU. Контроллеры домена выполняют аутентификацию и реплицируют каталог. DNS помогает находить доменные службы."], ["Kerberos", "Клиент получает билет TGT от KDC, затем сервисный билет для конкретного сервиса. Это не то же самое, что передача пароля каждому сервису. Синхронизация времени важна для протокола."], ["LDAP и GPO", "LDAP — протокол доступа к каталогу, не синоним Kerberos. GPO задают параметры компьютеров и пользователей; применимость зависит от области, фильтров и наследования. Группа безопасности используется для назначения прав, OU — для организации объектов и применения политик."], ["Защита", "Разделяй обычные и административные учётки, контролируй привилегированные группы, ограничивай административные маршруты, защищай резервные копии AD. Отслеживай изменения групп и политик."], ["Мониторинг", "Запрос TGT 4768, сервисного билета 4769 и события изменения групп полезны для расследования при включённом аудите. Большое число запросов само по себе не доказывает компрометацию."]], "diagram": ["Пользователь", "контроллер домена", "билет Kerberos", "сервис"], "case": ["AD: ошибка входа", "После изменения NTP часть клиентов перестала получать билеты Kerberos. Что проверить?", ["Расхождение времени между клиентом и DC", "Установить WAF", "Расширить диск SIEM", "Сменить все пароли"], [0], "Kerberos зависит от согласованного времени."], "questions": [{"q": "Сотрудник может войти в домен, но не открыть файловую папку. Какой слой проверить?", "o": ["Авторизацию и права ресурса", "Только проверку личности", "Только DNS вне домена", "Только резервную копию"], "a": [0], "e": "Успешная аутентификация не гарантирует разрешение на ресурс."}, {"q": "Что выполняет KDC в Kerberos?", "o": ["Выдаёт билеты аутентификации и доступа к сервисам", "Хранит все резервные копии", "Фильтрует HTTP", "Коррелирует сетевые события"], "a": [0], "e": "KDC обслуживает выдачу билетов."}, {"q": "Какой протокол предназначен для доступа к каталогу?", "o": ["LDAP", "Syslog", "NTP", "SMTP"], "a": [0], "e": "LDAP используется для операций с каталогом."}, {"q": "GPO не применяется к одному ПК. Что исследовать?", "o": ["Область действия, фильтрацию и наследование", "Только срок хранения SIEM", "Только объём БД", "Только WAF"], "a": [0], "e": "Применимость политик зависит от конфигурации AD."}, {"q": "Контроллеры домена не находятся по имени. Что проверить?", "o": ["DNS и записи доменных служб", "Только PAM", "Только DLP", "Только резервирование хранилища"], "a": [0], "e": "AD опирается на DNS."}, {"q": "Что даёт выделенная административная учётка?", "o": ["Разделение обычных и привилегированных действий", "Автоматическую защиту от всех атак", "Замену всех GPO", "Отказ от контроля привилегий"], "a": [0], "e": "Разделение уменьшает ненужное использование привилегий."}, {"q": "Что отражает событие 4769?", "o": ["Запрос сервисного билета Kerberos", "Создание локального файла", "Остановку DNS", "Любую смену пароля"], "a": [0], "e": "4769 относится к TGS."}, {"q": "Чем OU отличается от группы безопасности?", "o": ["OU организует объекты, группа используется для назначения прав", "OU всегда предоставляет доступ к файлам", "Группа заменяет все GPO", "Это полные синонимы"], "a": [0], "e": "Назначения различны."}, {"q": "Зачем синхронизация времени для Kerberos?", "o": ["Билеты и проверки времени зависят от согласованных часов", "Она увеличивает размер пароля", "Она заменяет KDC", "Она задаёт права к файлам"], "a": [0], "e": "Kerberos чувствителен к расхождению часов."}, {"q": "Какой тест подтверждает мониторинг изменения привилегий?", "o": ["Согласованное тестовое изменение группы и проверка события", "Только просмотр списка пользователей", "Только ping DC", "Только обновление антивируса"], "a": [0], "e": "Нужна проверка реального сценария."}]}, {"date": "08.12", "title": "IAM, IdM, PAM и MFA", "tag": "Identity", "blocks": [["AAA", "Authentication — проверка личности; Authorization — решение о полномочиях; Accounting — учёт действий. Успешная аутентификация не равна праву на ресурс."], ["IAM и IGA", "IAM — широкая область управления идентичностями и доступом. IdM/IGA автоматизируют жизненный цикл прав, согласования, пересмотр и отзыв доступа. Joiner–Mover–Leaver: приём, перевод, увольнение."], ["PAM", "PAM контролирует привилегированные учётки, хранение и ротацию секретов, сессии и временный доступ. Использование PAM требует закрывать неуправляемые обходные пути."], ["MFA и SSO", "MFA использует разные факторы: знание, владение, биометрический признак. Два пароля не являются двумя факторами. SSO — единый вход, не обязательно MFA. RBAC назначает права по ролям; ABAC использует атрибуты и условия."], ["Управление проектом", "Для внедрения нужны реестр приложений, владельцы ролей, матрица доступа, согласования, процессы HR, аварийный доступ и проверка отзыва прав."]], "diagram": ["HR", "IdM / IGA", "IAM", "приложение; PAM", "администратор"], "case": ["Отзыв доступа", "Подрядчик завершил работы. Какие действия нужны?", ["Отозвать временные права, завершить сессии и проверить журнал", "Оставить доступ до следующего года", "Удалить все журналы", "Дать общую admin-учётку"], [0], "Процесс Leaver должен закрывать пути доступа."], "questions": [{"q": "Сотрудник успешно вошёл, но не может согласовать платёж. Что отвечает за решение?", "o": ["Авторизация", "Аутентификация", "Accounting", "Резервное копирование"], "a": [0], "e": "Авторизация определяет доступные действия."}, {"q": "Сотрудника перевели в другой отдел, старые права остались. Что внедрить в процесс?", "o": ["Mover с пересмотром и отзывом прежних прав", "Только SSO", "Только SIEM", "Только смену пароля"], "a": [0], "e": "Жизненный цикл прав должен учитывать перевод."}, {"q": "Какие два фактора действительно различны?", "o": ["Пароль и аппаратный ключ", "Два пароля", "Пароль и PIN", "Два контрольных вопроса"], "a": [0], "e": "Знание и владение — разные факторы."}, {"q": "Администратор обходит PAM прямым SSH. Что сделать?", "o": ["Ограничить прямые маршруты и определить аварийный доступ", "Только включить запись PAM", "Увеличить EPS", "Отключить MFA"], "a": [0], "e": "Обходной путь лишает PAM контроля."}, {"q": "Какое решение соответствует RBAC?", "o": ["Права назначаются ролям по должностям", "Права определяются только IP", "Права выдаются всем одинаково", "Права меняет SIEM автоматически"], "a": [0], "e": "RBAC использует роли."}, {"q": "Что делает SSO?", "o": ["Позволяет единую аутентификационную сессию для ряда сервисов", "Всегда обеспечивает MFA", "Заменяет авторизацию", "Удаляет необходимость журналов"], "a": [0], "e": "SSO не равен MFA."}, {"q": "Что полезно проверить при увольнении?", "o": ["Отзыв доступов в приложениях и активных сессий по регламенту", "Только удаление записи HR", "Только отключение почты", "Только смену IP"], "a": [0], "e": "Нужно закрыть все значимые пути доступа."}, {"q": "Какая функция PAM наиболее важна для общих admin-паролей?", "o": ["Хранилище и управляемая ротация секретов", "Сетевой DPI", "Анализ HTTP", "Сканирование CVE"], "a": [0], "e": "PAM управляет привилегированными секретами."}, {"q": "Кто должен согласовывать бизнес-роли?", "o": ["Уполномоченные владельцы ресурсов и процессов", "Только поставщик PAM", "Только администратор SIEM", "Любой сотрудник"], "a": [0], "e": "Владельцы определяют допустимые права."}, {"q": "Как проверить минимальные привилегии?", "o": ["Испытать разрешённые и запрещённые операции тестовой роли", "Проверить только успешный вход", "Выдать всем роль администратора", "Сравнить число лицензий"], "a": [0], "e": "Нужны позитивные и негативные сценарии."}]}, {"date": "09.12", "title": "Криптография, PKI и СКЗИ", "tag": "Crypto", "blocks": [["Шифрование", "Симметричное шифрование использует общий секрет; асимметричное — пару ключей. Современные TLS-соединения используют согласование ключей и симметричную защиту трафика; конкретный механизм зависит от версии и набора алгоритмов."], ["Хеш и подпись", "Хеш — результат одностороннего преобразования фиксированной длины для конкретного алгоритма. Сам хеш не обеспечивает подлинность без доверенного эталона. Электронная подпись позволяет проверять целостность и происхождение при корректной инфраструктуре доверия."], ["PKI", "Сертификат связывает открытый ключ с субъектом. Проверяются цепочка доверия, срок, имя и назначение; отзыв проверяется в соответствии с политикой. Закрытые ключи защищают отдельно."], ["СКЗИ", "Средство криптографической защиты информации реализует криптографические функции. Не всякий TLS автоматически выполняет российские регуляторные требования. Применимость требований ФСБ и необходимость соответствующих средств определяют по конкретной системе."], ["Эксплуатация", "Веди реестр сертификатов и сроков, владельцев ключей, регламент замены и аварийного отзыва. Проверяй не только успешность соединения, но и корректную проверку доверия."]], "diagram": ["Клиент", "проверка сертификата", "согласование ключей", "защищённый канал"], "case": ["TLS: плановое обновление", "На коллекторе сертификат истечёт завтра. Как снизить риск простоя?", ["Согласовать замену, проверку доверия и тест отправки", "Отключить проверку сертификатов", "Остановить мониторинг навсегда", "Поменять формат событий"], [0], "Замена с испытанием снижает риск и сохраняет защищённость."], "questions": [{"q": "Что обеспечивает шифрование данных в первую очередь?", "o": ["Конфиденциальность", "Само по себе доступность", "Само по себе юридическую значимость подписи", "Обязательное резервирование"], "a": [0], "e": "Шифрование ограничивает чтение без ключа."}, {"q": "Как проверить происхождение и целостность подписанного файла?", "o": ["Проверить подпись и доверие к ключу подписанта", "Сравнить только длину файла", "Проверить только наличие TLS", "Сжать файл"], "a": [0], "e": "Подпись работает при корректном доверии."}, {"q": "Сертификат коллектора истёк. Что делать?", "o": ["Заменить по регламенту и проверить доверенную цепочку", "Отключить проверку TLS навсегда", "Отключить журналирование", "Увеличить RAM"], "a": [0], "e": "Нужно восстановить корректную проверку доверия."}, {"q": "Почему обычный хеш не доказывает авторство?", "o": ["Любой может вычислить хеш изменённого файла", "Хеш всегда обратим", "Хеш является сертификатом", "Хеш всегда скрывает файл"], "a": [0], "e": "Необходим доверенный эталон или подпись."}, {"q": "Какое свойство отличает асимметричную криптографию?", "o": ["Использует пару связанных ключей", "Всегда быстрее симметричной", "Не требует защиты закрытого ключа", "Всегда обеспечивает доступность"], "a": [0], "e": "Пара ключей — основное отличие."}, {"q": "TLS установлен, но проверка имени выключена. Какой риск?", "o": ["Подключение к ненадлежащему узлу", "Всегда переполнен диск", "Остановка всех DNS", "Потеря всех индексов"], "a": [0], "e": "Проверка имени связывает сертификат с ожидаемым узлом."}, {"q": "Что хранить в реестре сертификатов?", "o": ["Владельца, срок, назначение и порядок замены", "Только открытый ключ без контекста", "Все закрытые ключи в общем Excel", "Только EPS"], "a": [0], "e": "Реестр нужен для жизненного цикла, не для открытого хранения секретов."}, {"q": "Как проверить необходимость СКЗИ в регулируемой системе?", "o": ["Определить применимые требования и архитектуру каналов", "Считать любое HTTPS достаточным", "Купить любое СКЗИ до обследования", "Считать сертификацию необязательной всегда"], "a": [0], "e": "Решение зависит от применимых требований."}, {"q": "Что делать при компрометации закрытого ключа?", "o": ["Отозвать или заменить затронутые сертификаты и ключи по плану", "Продлить старый сертификат", "Только сменить IP", "Только очистить логи"], "a": [0], "e": "Компрометированный ключ нельзя считать доверенным."}, {"q": "Что проверяет доверенная цепочка сертификатов?", "o": ["Связь сертификата с доверенным центром и корректность подписей", "Размер диска", "Роль пользователя в ERP", "Срок хранения SIEM"], "a": [0], "e": "Цепочка подтверждает доверие при дополнительных проверках."}]}, {"date": "17.12", "title": "SIEM: сайзинг и архитектура", "tag": "SIEM", "blocks": [["Нагрузка", "EPS — events per second. Измеряй средний, пиковый и распределение нагрузки по источникам. Средний EPS нужен для объёма, пиковый — для пропускной способности и очередей. Лицензионную метрику уточняй у вендора."], ["Хранилище", "Сырой объём, ГБ/сут = EPS × байт × 86400 / 10⁹. Фактическое хранение зависит от индексации, сжатия, репликации и запаса. Например 1000 EPS при 500 байтах дают 43,2 ГБ/сут и 1,296 ТБ за 30 суток до коэффициентов."], ["Архитектура", "Коллекторы принимают данные; обработка парсит, нормализует и обогащает; коррелятор выявляет сценарии; хранилище обеспечивает поиск и retention. Реальная топология и распределение ролей зависят от продукта."], ["Отказоустойчивость", "Уточни RPO/RTO для SIEM, буферизацию, независимость узлов, репликацию и восстановление. Реплика не заменяет резервную копию; отказ сети может вызвать рост очередей."], ["Приёмка", "Согласуй нагрузочный профиль, тестовые источники, пропуски, задержку, поиск, переключение при отказе и запас. CPU/RAM определяют по рекомендациям вендора и испытаниям, а не одной формулой EPS."]], "diagram": ["Источники", "коллекторы", "обработка", "хранение / корреляция", "SOC"], "case": ["Сайзинг проекта", "Средний EPS 3000, пик 12000. Вендор подтвердил 5000 EPS на один узел на этом профиле. Какой вывод?", ["Для пика нужно не менее трёх таких узлов без резерва, проверить балансировку и HA", "Одного хватит по среднему", "Двух всегда хватит", "EPS не важен"], [0], "12000/5000 = 2,4, округляем вверх; HA и распределение рассчитываются дополнительно."], "questions": [{"q": "Источник даёт 12000 событий за минуту. Каков средний EPS?", "o": ["200", "120", "720000", "12000"], "a": [0], "e": "12000 / 60 = 200."}, {"q": "2000 EPS, 500 байт, 1 сутки. Какой сырой объём в десятичных ГБ?", "o": ["86,4", "43,2", "864", "8,64"], "a": [0], "e": "2000 × 500 × 86400 / 10⁹ = 86,4."}, {"q": "Что важнее для оценки пиковых очередей?", "o": ["Пиковая нагрузка и длительность всплесков", "Только средний EPS за месяц", "Только срок хранения", "Только число пользователей"], "a": [0], "e": "Очередь зависит от превышения скорости обработки."}, {"q": "Сырой объём за 30 дней 2 ТБ, коэффициент хранения 0,8, две полные копии, запас 25% к объёму. Итог?", "o": ["4 ТБ", "2,5 ТБ", "3,2 ТБ", "5 ТБ"], "a": [0], "e": "2 × 0,8 × 2 × 1,25 = 4 ТБ."}, {"q": "Почему нельзя выводить число CPU только из EPS?", "o": ["Влияют размер, правила, поиск, архитектура и продукт", "EPS не связан с нагрузкой", "CPU всегда равен числу источников", "Хранилище определяет все ресурсы"], "a": [0], "e": "Нужны данные конкретного решения и тесты."}, {"q": "Два источника по 100 EPS и пять по 20. Сумма?", "o": ["300 EPS", "220 EPS", "700 EPS", "120 EPS"], "a": [0], "e": "2 × 100 + 5 × 20 = 300."}, {"q": "Что даёт нормализация?", "o": ["Единую модель полей для разных источников", "Гарантию отсутствия атак", "Резервирование дисков", "Автоматическое шифрование всех данных"], "a": [0], "e": "Она делает события сопоставимыми."}, {"q": "Что проверить при переключении коллектора?", "o": ["Доставку, потери, дубликаты и время восстановления", "Только внешний вид интерфейса", "Только наличие второй лицензии", "Только состояние DNS"], "a": [0], "e": "Отказоустойчивость подтверждают испытания."}, {"q": "Почему реплика не заменяет backup?", "o": ["Ошибочное удаление может распространиться на реплики", "Реплика никогда не хранит данные", "Backup всегда мгновенный", "Реплика всегда недоступна"], "a": [0], "e": "Копии должны учитывать сценарии логических ошибок."}, {"q": "Какой документ фиксирует согласованный профиль нагрузки?", "o": ["Технические требования и программа испытаний", "Только договор страхования", "Только политика паролей", "Только список сотрудников"], "a": [0], "e": "Профиль и критерии должны быть согласованы."}]}, {"date": "19.12", "title": "SOC, реагирование и SOAR", "tag": "SOC", "blocks": [["SOC", "Security Operations Center — функция мониторинга и реагирования. L1 обычно проводит триаж, L2 расследует и реагирует, L3 занимается сложными расследованиями и улучшением обнаружения; границы ролей зависят от организации."], ["Инцидент", "Алерт — сигнал для проверки, инцидент — событие или совокупность событий, требующих реагирования по критериям организации. Сохраняй доказательства, время, источник и решения; не блокируй критический сервис без согласованных полномочий."], ["SOAR", "Security Orchestration, Automation and Response связывает системы и запускает плейбуки: триггер, обогащение, условия, действие, подтверждение и результат. Может принимать события не только от SIEM."], ["Метрики", "MTTD — среднее время обнаружения; MTTR неоднозначно расшифровывается, поэтому согласуй начальную и конечную точки (реагирование, восстановление или устранение). Считай также покрытие сценариев, долю ложных срабатываний, время очереди."], ["Проверка", "На учебном стенде проверь сценарий подозрительного входа: получение алерта, обогащение, подтверждение, ограничение доступа по регламенту и запись кейса. Для разрушительных действий нужен контроль."]], "diagram": ["Событие", "алерт", "триаж", "расследование", "реагирование", "выводы"], "case": ["SOC: подозрительная активность", "EDR выявил подозрительный процесс на сервере расчётов. Как действовать?", ["Обогатить алерт, проверить контекст, согласовать ограничение по регламенту", "Немедленно выключить весь ЦОД", "Закрыть алерт", "Удалить исходные события"], [0], "Критический актив требует осторожного реагирования и сохранения доказательств."], "questions": [{"q": "SIEM сформировала алерт о входе. Первое действие SOC?", "o": ["Проверить контекст и критерии инцидента", "Немедленно отключить весь домен", "Закрыть без проверки", "Удалить первичные события"], "a": [0], "e": "Алерт ещё не доказывает инцидент."}, {"q": "Какой шаг плейбука добавляет критичность актива?", "o": ["Обогащение", "Триггер", "Удаление данных", "Резервное копирование"], "a": [0], "e": "Обогащение даёт контекст."}, {"q": "SOAR получает HTTP 401 от коннектора. Что вероятнее проверить?", "o": ["Учётные данные, токен и полномочия", "Только EPS", "Только размер логов", "Только модель угроз"], "a": [0], "e": "401 связан с аутентификацией; права также проверяют по обстоятельствам."}, {"q": "Автоблокировка критического сервера может нарушить производство. Что предусмотреть?", "o": ["Точку подтверждения и регламент исключений", "Всегда автоматическую блокировку", "Отказ от журнала действий", "Полностью выключить SOC"], "a": [0], "e": "Критические действия требуют согласования."}, {"q": "Что показывает MTTD?", "o": ["Среднее время обнаружения", "Средний объём события", "Среднее время хранения", "Среднюю стоимость лицензии"], "a": [0], "e": "Метрика относится к обнаружению."}, {"q": "Что важно для воспроизводимости расследования?", "o": ["Временная шкала, источники доказательств и журнал действий", "Только устный отчёт", "Только итоговый статус", "Удаление исходных логов"], "a": [0], "e": "Документация позволяет проверять выводы."}, {"q": "Какая типичная задача L2?", "o": ["Углублённое расследование и согласованное реагирование", "Только первичный просмотр всех алертов", "Только закупка серверов", "Только разработка политики ПДн"], "a": [0], "e": "Роли различаются, но L2 обычно расследует глубже."}, {"q": "Правило даёт много ложных срабатываний. Что делать?", "o": ["Настроить условия и проверить покрытие на тестовых сценариях", "Выключить все правила", "Поднять порог до максимума без теста", "Скрыть алерты"], "a": [0], "e": "Настройка должна сохранять обнаружение нужных сценариев."}, {"q": "SOAR обязательно требует SIEM?", "o": ["Нет, может принимать сигналы и из других систем", "Да, без неё не запускаются плейбуки", "Да, только при наличии WAF", "Да, только в домене AD"], "a": [0], "e": "Источники триггеров могут быть различными."}, {"q": "Что считать успешной приёмкой плейбука?", "o": ["Ожидаемые шаги, обработку ошибок, подтверждение и запись результата", "Только создание плейбука", "Только успешный API-запрос", "Только число коннекторов"], "a": [0], "e": "Тест должен охватывать сценарий целиком."}]}, {"date": "21.12", "title": "Резервирование и непрерывность", "tag": "Resilience", "blocks": [["RPO / RTO", "RPO — допустимая потеря данных во времени; RTO — целевое время восстановления услуги. Цели определяет бизнес. Фактические показатели измеряются при испытании."], ["Копии", "Full — полная; incremental — изменения после последней копии; differential — после последней полной. Для восстановления инкрементальной цепочки обычно нужны полная и необходимые инкременты; продукт может реализовывать синтетические копии."], ["Защита копий", "3–2–1 — три копии включая оригинал, два типа носителей, одна вне площадки; изоляция и неизменяемость помогают против шифрования. Ограничивай администраторские права и проверяй ключи восстановления."], ["Испытания", "Восстанови копию в изолированной среде, проверь данные, зависимости, запуск приложения и бизнес-операцию, время и актуальность, оформи протокол. Не требуется останавливать рабочую систему ради типовой проверки копии."], ["BCP / DRP", "BCP обеспечивает продолжение критичных процессов, DRP — восстановление ИТ. Высокая доступность уменьшает простой при отказе отдельных узлов, но не защищает от всех ошибок и не заменяет backup."]], "diagram": ["Рабочая система", "backup", "изолированное хранилище", "тест восстановления"], "case": ["Проверка восстановления", "Backup завершён успешно, но никто не проверял запуск БД. Как закрыть риск?", ["Восстановить на изолированном стенде, проверить БД и измерить RPO/RTO", "Проверить только размер файла", "Удалить старые копии", "Считать задачу выполненной"], [0], "Проверка восстановления подтверждает работоспособность копии."], "questions": [{"q": "Цель RPO 1 ч, последняя копия 3 ч до сбоя. Что известно?", "o": ["RPO не выполнена", "RTO точно не выполнена", "Обе цели выполнены", "RPO выполнена"], "a": [0], "e": "Потенциальная потеря превышает один час."}, {"q": "Цель RTO 4 ч, сервис восстановлен через 3 ч. Что известно?", "o": ["RTO выполнена", "RPO точно выполнена", "Резервная копия всегда цела", "RTO нарушена"], "a": [0], "e": "Время восстановления меньше цели."}, {"q": "Почему копии в том же домене с общим админом опасны?", "o": ["Компрометация может затронуть оригинал и копии", "Они всегда медленные", "Они не могут содержать файлы", "Они нарушают TCP"], "a": [0], "e": "Общие полномочия создают общий риск."}, {"q": "Для чего дифференциальная копия?", "o": ["Хранит изменения после последней полной", "Хранит изменения только после предыдущей любой", "Всегда хранит весь диск", "Служит только для логов"], "a": [0], "e": "Дифференциальная привязана к полной."}, {"q": "Что доказывает успешность восстановления приложения?", "o": ["Запуск и проверенная бизнес-операция на стенде", "Только зелёный статус backup", "Только размер файла", "Только успешный ping"], "a": [0], "e": "Необходима функциональная проверка."}, {"q": "Что обеспечивает кластер высокой доступности?", "o": ["Снижение простоя при поддерживаемых отказах", "Защиту от любых удалений", "Всегда независимую резервную копию", "Нулевой RPO для всех данных"], "a": [0], "e": "HA не заменяет восстановление после логических ошибок."}, {"q": "Кто устанавливает RTO критичного бизнес-сервиса?", "o": ["Владелец бизнес-процесса с ИТ и ИБ", "Только поставщик дисков", "Только аналитик L1", "Только оператор backup"], "a": [0], "e": "Цели определяются потребностями бизнеса."}, {"q": "Что включает DRP?", "o": ["Порядок восстановления систем и зависимостей", "Только пароль администратора", "Только список CVE", "Только стоимость лицензии"], "a": [0], "e": "DRP описывает аварийное восстановление."}, {"q": "Почему стоит тестировать копию в изоляции?", "o": ["Чтобы избежать воздействия на рабочие данные и сервисы", "Чтобы не проверять целостность", "Чтобы не фиксировать время", "Чтобы автоматически устранить все угрозы"], "a": [0], "e": "Изоляция снижает риск испытаний."}, {"q": "Какая метрика описывает фактическую потерю данных?", "o": ["Интервал между точкой восстановленных данных и сбоем", "Число установленных агентов", "Время закупки лицензий", "Количество правил WAF"], "a": [0], "e": "Эта величина сопоставляется с RPO."}]}, {"date": "10.12", "title": "Контроль доступа к сети и идентичности: NAC, ZTNA, ITDR, IGA", "tag": "Доступ и архитектура", "blocks": [["NAC: допуск в сеть", "NAC проверяет устройство и пользователя до выдачи сетевого доступа, например посредством 802.1X и RADIUS. Устройства без требуемого состояния можно отправить в карантинный VLAN. NAC не заменяет межзонный экран."], ["ZTNA: доступ к приложению", "ZTNA выдаёт доступ к конкретному приложению по идентичности и контексту, а не автоматически ко всему сегменту. Учитывает состояние устройства и политику, но не исправляет уязвимости самого приложения."], ["IGA: жизненный цикл прав", "IGA связывает HR, каталоги и приложения: создание, изменение и отзыв прав при увольнении; согласование ролей и периодическая ревизия. PAM дополняет IGA контролем привилегированных сессий."], ["ITDR: угрозы идентичности", "ITDR анализирует события и конфигурации AD/IdP, изменение привилегий и аномальную аутентификацию. Может обогащать SIEM и инициировать согласованные меры. MFA и минимальные привилегии по-прежнему нужны."], ["Проект и испытания", "На обследовании фиксируем типы устройств, каталоги, приложения, текущую схему доступа и исключения. Пилот: штатный доступ, отказ неуправляемому устройству, отзыв прав, запись админ-сессии, детект изменения группы. Проверяем аварийный доступ и откат."]], "diagram": ["Устройство", "NAC", "Сеть", "ZTNA / PAM", "Приложение", "ITDR / SIEM"], "case": ["Подрядчик", "Подрядчику нужен один веб-сервис, без доступа к внутренней сети. Что выбрать первым?", ["ZTNA с политикой к приложению", "IGA без шлюза", "NDR в режиме зеркалирования", "DAM на БД"], [0], "ZTNA ограничивает предоставленный доступ конкретным приложением."], "questions": [{"q": "Неуправляемый ноутбук подключился к офисному порту. Какой класс наиболее прямо реализует допуск и карантин?", "o": ["NAC", "PAM", "ITDR", "IGA"], "a": [0], "e": "NAC контролирует сетевой допуск."}, {"q": "Подрядчику нужен доступ только к одному внутреннему веб-приложению. Что лучше соответствует задаче?", "o": ["VPN с маршрутом ко всей сети", "ZTNA с политикой на приложение", "NAC без прикладной политики", "PAM для общего доступа к ОС"], "a": [1], "e": "ZTNA выдаёт ограниченный доступ к приложению."}, {"q": "Увольнение сотрудника должно запускать отзыв прав в нескольких системах. Какой класс отвечает за жизненный цикл?", "o": ["MFA", "NDR", "IGA", "WAF"], "a": [2], "e": "IGA управляет жизненным циклом идентичностей и прав."}, {"q": "В каталоге неожиданно изменились привилегированные группы. Какой специализированный класс анализирует угрозы идентичности?", "o": ["DSPM", "NAC", "SCA", "ITDR"], "a": [3], "e": "ITDR специализируется на идентичностях."}, {"q": "Какие меры дополняют ITDR предотвращением несанкционированного доступа? Выбери все.", "o": ["MFA", "Пассивное зеркалирование трафика само по себе", "Минимальные привилегии", "Срок хранения архивов"], "a": [0, 2], "e": "MFA и минимальные привилегии снижают вероятность и последствия компрометации."}, {"q": "NAC отправил устройство в нужный VLAN. Что ещё проверяем для изоляции?", "o": ["Только номер VLAN", "Правила межзонной фильтрации", "Только журнал DHCP", "Только лицензию NAC"], "a": [1], "e": "VLAN не гарантирует отсутствие маршрутов между зонами."}, {"q": "Какой критерий приёмки лучше проверяет IGA?", "o": ["Консоль запускается", "Агент EDR работает", "После увольнения тестовые права отозваны во всех согласованных системах", "Доступны отчёты о CPU"], "a": [2], "e": "Проверяем результат процесса, а не наличие интерфейса."}, {"q": "Какой риск внедрения NAC требует плана отката?", "o": ["Изменение размера архивов SIEM", "Отсутствие отчётов SAST", "Изменение ключа БД", "Блокировка легитимных устройств"], "a": [3], "e": "Ошибка политики допуска может нарушить работу пользователей."}, {"q": "Что PAM даёт дополнительно к IGA?", "o": ["Запись и контроль привилегированной сессии", "Автоматическое устранение CVE", "Сканирование исходного кода", "Карантин VLAN"], "a": [0], "e": "PAM контролирует административные сессии."}, {"q": "Какой набор действий разумен перед внедрением ZTNA? Выбери все.", "o": ["Инвентаризация приложений и пользователей", "Закупка до выяснения требований", "Проверка доступности аварийного доступа", "Отключение журналов"], "a": [0, 2], "e": "Понимание приложений и аварийных сценариев уменьшает риск внедрения."}]}, {"date": "22.12", "title": "Безопасность приложений, данных и облака: AppSec, DSPM, CNAPP", "tag": "Углубление", "blocks": [["SAST, DAST и SCA", "SAST анализирует код без запуска. DAST проверяет работающий экземпляр приложения. SCA анализирует состав зависимостей и известные уязвимости. Эти классы дополняют друг друга; находки нуждаются в проверке и приоритизации."], ["WAF и API Security", "WAF анализирует HTTP-трафик перед приложением. API Security добавляет обнаружение интерфейсов и контроль злоупотреблений API. Исправление ошибок бизнес-логики и авторизации остаётся задачей приложения."], ["DSPM, DAM, DLP", "DSPM помогает обнаружить чувствительные данные и рискованные настройки доступа. DAM наблюдает активность БД. DLP контролирует каналы передачи информации. У всех разные точки контроля и ограничения."], ["CSPM, CWPP и CNAPP", "CSPM оценивает настройки облачной инфраструктуры. CWPP защищает рабочие нагрузки. CNAPP объединяет несколько возможностей cloud-native защиты; состав зависит от реализации."], ["Проверка эффективности", "BAS помогает контролируемо проверять меры и детекты в согласованном контуре. В проекте нужны перечень требований, границы, владельцы, критерии приёмки, план отката и порядок триажа."]], "diagram": ["Код / зависимости", "SAST + SCA", "Тестовое приложение", "DAST", "WAF / API", "SIEM / SOC"], "case": ["Облачное хранилище", "Нужно обнаружить чувствительные данные с избыточными правами в разных хранилищах. Что выбрать?", ["DSPM", "DAST", "PAM", "NDR"], [0], "DSPM связывает чувствительность данных и конфигурацию доступа."], "questions": [{"q": "Команда хочет выявлять дефекты собственного кода до запуска. Какой инструмент подходит?", "o": ["DAST", "SAST", "DAM", "CSPM"], "a": [1], "e": "SAST анализирует код без запуска."}, {"q": "Сборка содержит сторонние библиотеки. Что помогает обнаружить известные CVE в них?", "o": ["SCA", "WAF", "ITDR", "CWPP"], "a": [0], "e": "SCA анализирует состав зависимостей."}, {"q": "На стенде требуется проверка поведения работающего HTTP-приложения извне.", "o": ["SAST", "SCA", "DAST", "SGRC"], "a": [2], "e": "DAST проверяет запущенное приложение."}, {"q": "Необходимо найти неизвестные API и аномальные сценарии их использования. Что наиболее специализировано?", "o": ["NGFW", "Backup", "MDM", "API Security"], "a": [3], "e": "API Security ориентирован на API-инвентаризацию и угрозы."}, {"q": "Какой класс наиболее непосредственно выявляет рискованные настройки облачных ресурсов?", "o": ["CSPM", "DAM", "SEG", "PAM"], "a": [0], "e": "CSPM анализирует облачные конфигурации."}, {"q": "Какой класс защищает облачные рабочие нагрузки в runtime?", "o": ["DSPM", "CWPP", "IGA", "SCA"], "a": [1], "e": "CWPP ориентирован на рабочие нагрузки."}, {"q": "Нужно найти чувствительные данные и избыточные права к ним. Что соответствует задаче?", "o": ["DAST", "ITDR", "DSPM", "WAF"], "a": [2], "e": "DSPM фокусируется на данных и доступе к ним."}, {"q": "Заказчик хочет наблюдать действия и запросы в СУБД. Какой класс наиболее специализирован?", "o": ["CSPM", "NAC", "SCA", "DAM"], "a": [3], "e": "DAM контролирует активность БД."}, {"q": "Какие условия обязательны для полезной безопасной проверки детектов через BAS? Выбери все.", "o": ["Согласованный контур и разрешения", "Отключение мониторинга", "Заранее определённые критерии успешности", "Запуск без информирования владельцев"], "a": [0, 2], "e": "BAS требует контролируемого контура и проверяемых критериев."}, {"q": "Какой набор лучше соответствует многослойной защите веб-приложения? Выбери все подходящие компоненты.", "o": ["SAST/SCA в сборке", "DAST на тестовом стенде", "WAF перед приложением", "Отказ от исправления найденных дефектов"], "a": [0, 1, 2], "e": "Проверки разработки и runtime-барьеры дополняют друг друга; дефекты исправляют."}]}];
